"use strict";

/**
 * v3.5.5 (3P Matrix 4.5.4 parity): this list ships as a precompiled JSON string in TopSitesFilter.default.js,
 * generated by tools/gen-data-defaults.mjs from data/TopSitesFilter.json, and is parsed on its first
 * lookup (util/LazyJson.js) — never at service-worker start.
 *
 * TopSitesFilter.js
 *
 * "Is this registrable domain one of the web's most popular sites?" —
 * backed by a Bloom filter built from the Chrome UX Report (CrUX) top-100K
 * site list, unioned with every Brands.json website and GovSuffixes.json
 * suffix (real Chrome user-traffic data plus the shared brand/gov-site
 * list; see tools/build-top-sites-filter.mjs for how
 * data/TopSitesFilter.json is built — v3.2.0, 3P Matrix alignment
 * §3, shrank this from the full top-1M to the top-100K + brand/gov union).
 *
 * This serves two jobs:
 *   - test 1 of protection/LookalikeDomainCheck.js (v3.2.0): "is the host
 *     ITSELF already a popular/real site?" — if so, stop, nothing to flag.
 *   - test 3 of that same check: it generates a handful of
 *     character-substitution variants of a download URL's host name-part
 *     (e.g. "arnazon" -> "amazon" via the rn->m lookalike) and asks "does
 *     THIS variant match a real top site?" — a much stronger signal than
 *     the hostname merely being unfamiliar.
 *
 * A Bloom filter never false-negatives (mightBeTopSite() returning false is
 * certain) but can false-positive at the ~1% rate it was built at (see
 * build-top-sites-filter.mjs's CONFIG.FALSE_POSITIVE_RATE) — so a true
 * result here is a "maybe", not a certainty, and callers must weight it
 * accordingly (this module intentionally has no scoring opinion of its
 * own; see FilenameUrlHeuristics.js's SCORING_CONFIG for that).
 *
 * Same init/setData/resetToDefault guard convention as PublicSuffixList.js
 * and the rest of the extracted-data modules: the active filter is rebuilt
 * wholesale, never mutated incrementally, so a refresh can never leave two
 * datasets' bits live at once.
 */
import { TopSitesFilterDefaultJson } from "./TopSitesFilter.default.js";
import { lazyJson } from "./LazyJson.js";
import { BloomFilter } from "./BloomFilter.js";

export const TopSitesFilter = (function () {

    // ── In-memory state — rebuilt wholesale by setData()/resetToDefault() ──
    let filter = null;

    function loadFrom(data) {
        filter = BloomFilter.fromBase64(data.size, data.numHashes, data.bitsBase64);
    }
    // 3P Matrix 4.5.4 (perf P4): built on the first lookup, not at service-worker start (util/LazyJson.js).
    const defaultData = lazyJson(TopSitesFilterDefaultJson);
    function ensureLoaded() { if (filter === null) loadFrom(defaultData()); }   // guard: never queried with "no data yet"

    /**
     * @param {string} registeredDomain — a registrable domain (name.tld),
     *   e.g. from PublicSuffixList.getRegisteredDomain() — NOT a full
     *   hostname with subdomains, which this filter was never built on.
     * @returns {boolean} true = possibly a top-1M site (or a ~1% false
     *   positive); false = definitely not.
     */
    function mightBeTopSite(registeredDomain) {
        if (!registeredDomain) return false;
        ensureLoaded();
        return filter.has(registeredDomain.toLowerCase());
    }

    function setData(newData) {
        loadFrom(newData);
    }

    function resetToDefault() {
        filter = null;                                // released; rebuilt from the default on next use
    }

    return { mightBeTopSite, setData, resetToDefault };
})();
